ns:RegisterSpecGuide("WARRIOR", "Arms", {
	role = "melee",
	stats = { "Hit Rating (Until Soft cap)", "Armor Penetration", "Strength/Critical Strike Rating", "Expertise", "Agility", "Haste Rating", "Attack Power" },
	enchants = {
		{ slot = "Head", options = { { kind = "item", id = 50367, enchant = 3817, name = "Arcanum of Torment" } },
		  note = "Arcanum of Torment from Knights of the Ebon Blade revered reputation is our only option for a helm enchant this expansion. While it requires revered reputation, Knights of the Ebon Blade will be one of the first factions you target for reputation grinding due to the powerful reward of Death-Inured Sabatons at exalted." },
		{ slot = "Shoulder", options = { { kind = "item", id = 50335, enchant = 3808, name = "Greater Inscription of the Axe" }, { kind = "item", id = 44131, enchant = 3875, name = "Lesser Inscription of the Axe" } },
		  note = "The Sons of Hodir provides the shoulder enchants for the WotLK expansion. While the strong version only is obtainable at exalted, which can be a moderate grind if you don't spend gold on Relic of Ulduar, the slightly weaker version Lesser Inscription of the Axe is obtainable at honoured, and is equal in value to the Aldor/Scryer exalted enchants." },
		{ slot = "Back", options = { { kind = "item", id = 41111, enchant = 3605, name = "Flexweave Underlay" }, { kind = "spell", id = 60663, enchant = 1099, craft = "Enchanting" } },
		  note = "While Flexweave Underlay is an engineering exclusive enchant, and only provides 1 more agility than the standard cloak enchant {spell:60663}, it also has a bonus on use effect of slowing your falling speed, making it a useful utility enchant while adventuring!" },
		{ slot = "Chest", options = { { kind = "spell", id = 60692, enchant = 3832, craft = "Enchanting" } },
		  note = "{spell:60692} is the best option available for raiding due to the small stat increase, although {spell:44623} can also be used as a cheaper option." },
		{ slot = "Wrist", options = { { kind = "spell", id = 57683, enchant = 3756, craft = "Leatherworking" }, { kind = "spell", id = 44575, enchant = 3845, craft = "Enchanting" } },
		  note = "{spell:57683} is the highest attack power enchant available for Arms Warrior, but is only available if you choose Leatherworking - a not extremely desirable profession. The other option is the more readily available {spell:44575}." },
		{ slot = "Hands", options = { { kind = "spell", id = 54999, enchant = 3604, craft = "Engineering" }, { kind = "spell", id = 60668, enchant = 1603, craft = "Enchanting" } },
		  note = "{spell:54999} gives us an extra cooldown that can be used with our other abilities to enhance our burst DPS, giving us greater windows to deal increased damage, but is only available for engineers. However, due to the fact that it ends up being more difficult to sync up with our cooldowns, which are 90s in length, as well as the fact that haste is a less desirable stat for us than other DPS specs, means that Arms can quite comfortably choose to use {spell:60668} as an alternative." },
		{ slot = "Waist", options = { { kind = "spell", id = 54793, enchant = 3601, craft = "Engineering" } },
		  note = "Available only for engineers, this unique attachment allows the ability to throw a {spell:54712} every 6 minutes. While of low impact, it does provide some extra damage while questing or on a budget." },
		{ slot = "Legs", options = { { kind = "item", id = 38374, enchant = 3823, name = "Icescale Leg Armor" }, { kind = "item", id = 38372, enchant = 3326, name = "Nerubian Leg Armor" } },
		  note = "Similarly to TBC, the only options for leg enchants come in the form of attack power/critical strike rating buffs. While the cheaper option is quite significantly worse than the more expensive one, simply having one is a large DPS increase due to the high stat Budget on these items." },
		{ slot = "Feet", options = { { kind = "spell", id = 55016, enchant = 3606, craft = "Engineering" }, { kind = "spell", id = 34007, enchant = 2939, craft = "Enchanting" }, { kind = "spell", id = 60763, enchant = 1597, craft = "Enchanting" } },
		  note = "WotLK provides a large range of Boot enchants, all of which can be used in different circumstances. The simplest all around option is {spell:34007}, passively increasing our movement speed while also giving a small amount of agility. If mobility is not a concern, then {spell:60763} provides a large attack power increase, while {spell:60623} helps us if we're missing hit rating for cap, while also giving us a small amount of critical strike rating.\n\nHowever, the strongest overall option is by far {spell:55016}. Providing a modest amount of a strong stat in critical strike rating, it also provides a unique enchant effect - a rocket boot style movement speed increase. The on demand burst of spe" },
		{ slot = "Weapon", options = { { kind = "spell", id = 59621, enchant = 3789, craft = "Enchanting" } },
		  note = "The only viable weapon enchant for Warriors in WotLK, {spell:59621} provides a massive amount of extra attack power with a high uptime proc." },
		{ slot = "Ranged", options = { { kind = "item", id = 41167, enchant = 3608, name = "Heartseeker Scope" } },
		  note = "Heartseeker Scope is the best enhancement for your ranged weapon. Because Warriors do not use ranged weapons a lot, this is considered a very low priority enhancement." },
		{ slot = "Ring", options = { { kind = "spell", id = 44645, enchant = 3839, craft = "Enchanting" } },
		  note = "{spell:44645} allows the player to enchant their ring with a moderate attack power increase. However, this is only available to enchanters." },
	},
	gems = {
		{ slot = "Meta", options = { { kind = "item", id = 41398, name = "Relentless Earthsiege Diamond" }, { kind = "item", id = 41285, name = "Chaotic Skyflare Diamond" } },
		  note = "Relentless Earthsiege Diamond edges out Chaotic Skyflare Diamond very slightly due to one small advantage - the need to only use 1 blue gem, as opposed to 2. While a slight DPS loss from the conversion of Agility to critical strike chance as opposed to Critical Rating is seen, the ability to use an extra Bold Cardinal Ruby or Fractured Cardinal Ruby allows a higher DPS increase. Chaotic Skyflare Diamond can still see uses when multiple strong Blue sockets are present on gear." },
	},
	priority = {
		{ 47465, "" },
		{ 7386, "" },
		{ 47471, "" },
		{ 7384, "" },
		{ 46924, "" },
		{ 47486, "" },
		{ 47475, "" },
		{ 47450, "" },
	},
	opener = "",
})

