ns:RegisterSpecGuide("WARRIOR", "Protection", {
	role = "tank",
	stats = {  },
	enchants = {
		{ slot = "Head", options = { { kind = "item", id = 50369, enchant = 3818, name = "Arcanum of the Stalwart Protector" } },
		  note = "Both the Arcanum of the Stalwart Protector, that you can buy once Revered with the Argent Crusade, and the Engineering (410) exclusive {spell:67839} are valid options for a head enchant.\nArcanum of the Stalwart Protector provides slightly more overall survivability in the form of bonus avoidance from the 20 defense rating, while {spell:67839} comes with 8 more stamina, providing more EHP and more value against enemies dealing magic or true damage. Each enchant will perform best in different situations. If you can afford to lose the defense from Arcanum of the Stalwart Protector and remain immune to critical strikes, then {spell:67839} is a more versatile choice." },
		{ slot = "Shoulder", options = { { kind = "item", id = 44957, enchant = 3852, name = "Greater Inscription of the Gladiator" } },
		  note = "As surprising as it may sound, the PvP enchant Greater Inscription of the Gladiator (10.000 an item) is the best option for a tank since it's the only shoulders enchant providing stamina. Yes, that means we are once again forced to do a little amount of PvP in WotLK even when gearing strictly for PvE. \nThe alternative Greater Inscription of the Pinnacle enchant is barely an upgrade from the TBC enchant and provides only avoidance which is inefficient against magic or true damage boss profiles.\n\nThe Inscription's exclusive {spell:61119}, because it's based on the stats profile of the Greater Inscription of the Pinnacle, is also disappointing and barely better than the PvP enchant against phys" },
		{ slot = "Back", options = { { kind = "item", id = 41111, enchant = 3605, name = "Flexweave Underlay" }, { kind = "spell", id = 60663, enchant = 1099, craft = "Enchanting" } },
		  note = "Flexweave Underlay (Engineering (375) exclusive) or {spell:60663} provide more stats overall in the form of threat, avoidance and armor than any other enchant available in WotLK. {spell:44591} remains an acceptable option if you are scrambling for defense rating to reach critical strikes immunity." },
		{ slot = "Chest", options = { { kind = "spell", id = 60692, enchant = 3832, craft = "Enchanting" } },
		  note = "{spell:60692} provides the most value for the Protection with an equal balance of threat, mitigation and avoidance that far outweighs the alternatives.\nJust like cloak enchants, {spell:47766} is an acceptable choice to reach your critical strikes immunity early on in the expansion." },
		{ slot = "Wrist", options = { { kind = "spell", id = 62256, enchant = 3850, craft = "Enchanting" } },
		  note = "No other enchant comes close to {spell:62256} for bracers.\nIf you are proficient in Leatherworking, your profession perk {spell:57690} will replace the bracers enchant for a bonus of +62 stamina." },
		{ slot = "Hands", options = { { kind = "spell", id = 63770, enchant = 3860, craft = "Engineering" }, { kind = "spell", id = 44529, enchant = 3222, craft = "Enchanting" }, { kind = "item", id = 38376, enchant = 3330, name = "Heavy Borean Armor Kit" }, { kind = "spell", id = 44488, enchant = 3234, craft = "Enchanting" }, { kind = "spell", id = 44625, enchant = 3253, craft = "Enchanting" } },
		  note = "Tanks skilled in Engineering can enchant their gloves with the {spell:63770} which provides a substantial mitigation increase over other gloves enchants equivalent to roughly 70 stamina worth of EHP. This gloves enchant really makes Engineering a must-have for tanks, paired with the long list of explosives, mobility bonuses and QoL from Engineering in general. \n\nFor non-engineers, the options are {spell:44529}, Heavy Borean Armor Kit and {spell:44488}. {spell:44529} provides a good balance of threat, mitigation and avoidance and more total value overall, while the pure stamina of the Heavy Borean Armor Kit is the most helpful when soaking heavy magic damage. {spell:44488} only provides threa" },
		{ slot = "Legs", options = { { kind = "item", id = 38373, enchant = 3822, name = "Frosthide Leg Armor" }, { kind = "item", id = 38371, enchant = 3325, name = "Jormungar Leg Armor" } },
		  note = "Frosthide Leg Armor and Jormungar Leg Armor are your usual high stamina and agility leg armor enchants crafted by leatherworkers." },
		{ slot = "Feet", options = { { kind = "spell", id = 47901, enchant = 3232, craft = "Enchanting" } },
		  note = "{spell:47901} is your go-to boots enchant as a tank for WotLK. While it provides less stamina than {spell:44528}, the bonus movement speed that can not be accessed from other means as a warrior is invaluable, both as a quality of life improvement but also to outrun some mechanics.\nSituationally, you may want to use Nitro Boosts (Engineering (375) exclusive) for a big burst of speed over 5 seconds instead of the constant 8% speed increase. Ideally, you want to always carry a pair of boots with each enchant for different situations and encounters." },
		{ slot = "Ring", options = { { kind = "spell", id = 59636, enchant = 3791, craft = "Enchanting" } },
		  note = "If you are an enchanter, you can enchant your rings with 2x30 stamina {spell:59636} (Enchanting (400) required), for a total profession bonus of +60 stamina. Just like in TBCC, these enchants are deactivated if you unlearn Enchanting." },
		{ slot = "Weapon", options = { { kind = "spell", id = 59619, enchant = 3788, craft = "Enchanting" } },
		  note = "Wrath of the Linch King introduces many new weapons enchants designed for tanks, such as {spell:64441}, {spell:44576}, {spell:64579}. While the design ideas are interesting, ultimately the effects are all lackluster.\n\nIn the end, the passive stats of {spell:59619} provide the most benefit for the Protection if you value threat at all, while TBC's iconic {spell:27984} remains the best weapon enchant for damage mitigation thanks to its high agility proc. However, be aware that both the proc rate and haste provided by {spell:28093} are reduced for lvl 80 characters. \n\nAlternatively, {spell:64579} is a good tank enchant added in WotLK and a decent choice for survivability. It's a \"smart\" enchant" },
		{ slot = "OffHand", options = { { kind = "item", id = 44936, enchant = 3849, name = "Titanium Plating" } },
		  note = "Titanium Plating provides significantly more overall value than any other enchant, balanced between threat and mitigation, and should be your go-to in most situations. However, in some cases you may prefer {spell:34009} against magic damage. {spell:44489} is an option if you are desperate for defense rating to reach the critical strikes immunity." },
		{ slot = "Ranged", options = { { kind = "item", id = 41167, enchant = 3608, name = "Heartseeker Scope" } },
		  note = "While most tanks do not bother enchanting their ranged weapon because it's rarely used, especially with the addition of {spell:57755}, Heartseeker Scope is technically the best enchant to increase your threat when shooting at something." },
	},
	gems = {
		{ slot = "Meta", options = { { kind = "item", id = 41380, name = "Austere Earthsiege Diamond" } },
		  note = "The Austere Earthsiege Diamond beats all other options by a landslide and is going to be your go-to meta gem for all of Wrath of the Lich King as a tank. It requires 2 blue gems and 1 red gem to activate, which conveniently are the best picks for a Protection anyway." },
		{ slot = "Blue", options = { { kind = "item", id = 40119, name = "Solid Majestic Zircon" }, { kind = "item", id = 40008, name = "Solid Sky Sapphire" } },
		  note = "Pure stamina gems are the most common and efficient choice, both for the individual value of stamina outshining other primary stats and because you get 50% more of it on gems compared to other stats. However, a +6 stamina socket bonus is worth considering using an hybrid purple or green gem to activate." },
		{ slot = "Red", options = { { kind = "item", id = 40141, name = "Guardian's Dreadstone" }, { kind = "item", id = 49110, name = "Nightmare Tear" }, { kind = "item", id = 40034, name = "Guardian's Twilight Opal" }, { kind = "item", id = 40138, name = "Regal Dreadstone" }, { kind = "item", id = 40023, name = "Shifting Twilight Opal" }, { kind = "item", id = 40031, name = "Regal Twilight Opal" } },
		  note = "If the socket bonus is worth activating, your go-to gem for red sockets is the Guardian's purple hybrid. \"Guardian\" is a new gem affix introduced with WotLK that combines expertise and stamina, both of the preferred stats for a tank.\n\nAlternatively, for a more defensive-oriented pick or if you don't need any more expertise, the Shifting Dreadstone is the best hybrid gem for mitigation. While Regal Dreadstone provides ever so slightly more damage mitigation, the additional threat from agility without sacrificing survivability gives you more bang for your bucks. \n\nWith the addition of epic gems in Phase 3, and if you don't have any valuable yellow socket in the rest of your gear set, a red soc" },
		{ slot = "Yellow", options = { { kind = "item", id = 49110, name = "Nightmare Tear" }, { kind = "item", id = 40088, name = "Vivid Forest Emerald" }, { kind = "item", id = 40089, name = "Enduring Forest Emerald" }, { kind = "item", id = 40015, name = "Thick Autumn's Glow" } },
		  note = "Yellow sockets are ideal to adjust your defense or hit rating with yellow or green gems, especially early when reaching critical strikes immunity can be challenging before obtaining BiS items. A yellow socket is also a prime choice to slot in your unique-equipped Nightmare Tear, a prismatic gem that matches any color, and whose total stats amount to more than the rare and epic green gems." },
	},
	priority = {
	},
	opener = "",
})
